// Correct but slow: recalculate the entire window sum each time, O(n * k)
function maxWindowSum(sales, k) {
  let best = -Infinity;
  for (let i = 0; i + k <= sales.length; i++) {
    let sum = 0;
    for (let j = i; j < i + k; j++) {
      sum += sales[j];
    }
    best = Math.max(best, sum);
  }
  return best;
}

exercises.solution:
function maxWindowSum(sales, k) {
  if (k <= 0 || k > sales.length) return null;

  // Sum of the first k-day window
  let sum = 0;
  for (let i = 0; i < k; i++) sum += sales[i];

  let best = sum;
  // Move the window one day at a time: add the entering day and subtract the leaving day
  for (let i = k; i < sales.length; i++) {
    sum += sales[i] - sales[i - k];
    best = Math.max(best, sum);
  }
  return best;
}

