// Sort by each task’s dependency count: appears correct for simple cases
// But fails for long dependency chains and never checks for cycles
function buildOrder(tasks, deps) {
  const count = new Map(tasks.map((t) => [t, 0]));
  for (const [, after] of deps) count.set(after, count.get(after) + 1);
  return [...tasks].sort((a, b) => count.get(a) - count.get(b));
}

exercises.solution:
function buildOrder(tasks, deps) {
  const next = new Map(tasks.map((t) => [t, []]));
  const inDegree = new Map(tasks.map((t) => [t, 0]));
  for (const [before, after] of deps) {
    next.get(before).push(after);
    inDegree.set(after, inDegree.get(after) + 1);
  }

  // Start with tasks that do not have to wait for another task
  const queue = tasks.filter((t) => inDegree.get(t) === 0);
  const order = [];
  let head = 0;
  while (head < queue.length) {
    const task = queue[head++];
    order.push(task);
    for (const n of next.get(task)) {
      inDegree.set(n, inDegree.get(n) - 1);
      if (inDegree.get(n) === 0) queue.push(n);
    }
  }

  if (order.length !== tasks.length) {
    throw new Error('dependency cycle: cannot determine an execution order');
  }
  return order;
}

