// BFS finds the route with the fewest stops, rather than the cheapest route
function cheapestRoute(graph, start, goal) {
  const queue = [[start]];
  const seen = new Set([start]);
  while (queue.length > 0) {
    const path = queue.shift();
    const node = path[path.length - 1];
    if (node === goal) {
      let cost = 0;
      for (let i = 1; i < path.length; i++) {
        cost += graph.get(path[i - 1]).find((e) => e.to === path[i]).cost;
      }
      return { cost, path };
    }
    for (const { to } of graph.get(node) ?? []) {
      if (!seen.has(to)) {
        seen.add(to);
        queue.push([...path, to]);
      }
    }
  }
  return null;
}

exercises.solution:
function cheapestRoute(graph, start, goal) {
  for (const edges of graph.values()) {
    for (const e of edges) {
      if (e.cost < 0) throw new Error('Dijkstra cannot handle negative costs');
    }
  }

  const dist = new Map([[start, 0]]);
  const prev = new Map();
  const heap = new MinHeap();
  heap.push(start, 0);

  while (heap.size > 0) {
    const { item: node, priority: d } = heap.pop();
    if (d > dist.get(node)) continue; // Stale entry remaining in the heap
    if (node === goal) break;
    for (const { to, cost } of graph.get(node) ?? []) {
      const nd = d + cost;
      if (nd < (dist.get(to) ?? Infinity)) {
        dist.set(to, nd);
        prev.set(to, node);
        heap.push(to, nd);
      }
    }
  }

  if (!dist.has(goal)) return null;
  const path = [goal];
  while (path[0] !== start) path.unshift(prev.get(path[0]));
  return { cost: dist.get(goal), path };
}
